// Editorun KENDI yazdigi dosyalar watcher'da yankilanmasin (reload dongusu/
    // yazma sirasinda text buffer sifirlanmasi olmasin).
    public static void NoteSelfWrite(string fullPath)
        => _selfWrites[System.IO.Path.GetFullPath(fullPath)] = GLFW.GetTime();

public static void Start(string assetsPath)
    {
        _assetsRoot = System.IO.Path.GetFullPath(assetsPath);
        _fsw = new FileSystemWatcher(assetsPath)
        {
            IncludeSubdirectories = true,
            NotifyFilter = NotifyFilters.LastWrite | NotifyFilters.FileName | NotifyFilters.DirectoryName,
        };
        _fsw.Changed += OnFsEvent;
        _fsw.Created += OnFsEvent;
        _fsw.Deleted += OnFsEvent;
        _fsw.Renamed += (_, e) => { _events.Enqueue(e.OldFullPath); _events.Enqueue(e.FullPath); };
        _fsw.EnableRaisingEvents = true;
    }

// Ana thread, her frame: olaylari sinifla + biten derlemeyi uygula.
    public static void Tick(double now)
    {
        while (_events.TryDequeue(out var path))
        {
            string full;
            try { full = System.IO.Path.GetFullPath(path); }
            catch { continue; }
            if (_selfWrites.TryGetValue(full, out double at) && now - at < SelfWriteMaskSeconds)
                continue; // bizim yazdigimiz dosyanin yankisi
            if (full.EndsWith(".meta", StringComparison.OrdinalIgnoreCase))
                continue; // sahibiyle birlikte gelir; tek basina ilginc degil
            _lastEventAt = now;
            if (full.EndsWith(".cs", StringComparison.OrdinalIgnoreCase))
            {
                if (!full.Replace('\\', '/').Contains("/Editor/"))
                    _codeDirty = true;
            }
            else
            {
                _assetDirty.Add(full);
            }
        }

        // Debounce doldu: birikenleri isle (derleme + asset refresh'leri).
        if ((_codeDirty || _assetDirty.Count > 0) && now - _lastEventAt >= DebounceSeconds)
        {
            if (_codeDirty)
            {
                _codeDirty = false;
                RequestBuild();
            }
            if (_assetDirty.Count > 0)
            {
                foreach (var full in _assetDirty)
                    ApplyAssetChange(full);
                _assetDirty.Clear();
            }
        }

        if (_building is { IsCompleted: true })
        {
            var job = _building.Result;
            _building = null;
            Apply(job);
            if (_rebuildPending)
            {
                _rebuildPending = false;
                RequestBuild();
            }
        }
    }

// ANA THREAD: dis asset degisikligini uygun en hafif yolla yansit.
    static void ApplyAssetChange(string full)
    {
        var assets = App.Assets;
        if (assets == null || !full.StartsWith(_assetsRoot, StringComparison.OrdinalIgnoreCase))
            return;
        string rel = System.IO.Path.GetRelativePath(_assetsRoot, full).Replace('\\', '/');
        string ext = System.IO.Path.GetExtension(full).ToLowerInvariant();

        // Yeni/silinen dosyalar guid kazansin/dussun (tek dosya icin de ucuz tarama).
        if (!File.Exists(full) || assets.PathToGuid(rel) == null)
            assets.ScanMetas(createMissing: true);

        switch (ext)
        {
            case ".png" or ".jpg" or ".jpeg":
                // Yerinde piksel patch'i: sahne/play/referanslar hic bozulmaz.
                if (assets.ReloadTexture(rel))
                    EditorLog.Info($"texture patched in-place: {rel}");
                AtlasBuilder.MarkDirtyByMember(rel); // uye oldugu gruplar tazelenir
                break;
            case ".prefab":
                assets.InvalidatePrefab(rel);
                App.EditScene.ReexpandPrefabs();
                EditorLog.Info($"prefab reloaded: {rel}");
                if (PlayMode.State != PlayState.Editing && PlayMode.HotReload == HotReloadMode.Instant)
                    PlayMode.DoHotReload();
                break;
            case ".scene":
                if (App.EditScene.Path != null
                    && string.Equals(System.IO.Path.GetFullPath(App.EditScene.Path), full, StringComparison.OrdinalIgnoreCase))
                {
                    // Cakisma politikasi: kaydedilmemis duzenleme varsa BELLEK kazanir.
                    if (App.EditScene.Dirty)
                        EditorLog.Warning($"scene changed on disk but has unsaved edits, keeping in-memory: {rel} (save to overwrite)");
                    else
                    {
                        App.ReloadScene();
                        EditorLog.Info($"scene reloaded from disk: {rel}");
                    }
                }
                break;
            case ".asset":
                AssetChangeVersion++;
                LastChangedAsset = full;
                if (File.Exists(full) && AtlasBuilder.IsAtlasGroupAsset(full))
                    AtlasBuilder.MarkDirtyGroup(rel);
                EditorLog.Info($"asset changed: {rel}");
                break;
        }
    }

// El ile de cagrilabilir (Project/Compile+Load Code menusu buna yonlenebilir).
    public static void RequestBuild()
    {
        if (_building != null)
        {
            _rebuildPending = true;
            return;
        }
        Status = "Compiling...";
        Failed = false;
        EditorLog.Info("code change detected, compiling...");
        var project = App.Project;
        _building = Task.Run(() => GameCode.CompileOnly(project));
    }

// Ana thread: basari = ALC swap + katalog + sahne yeniden; hata = log, eski kod yasar.
    static void Apply(GameCode.CompileJob job)
    {
        if (!job.Ok)
        {
            Failed = true;
            int n = 0;
            foreach (var line in job.Output.Split('\n'))
            {
                var t = line.Trim();
                if (t.Contains(": error ") && n < 30)
                {
                    EditorLog.Error(t);
                    n++;
                }
            }
            if (n == 0)
                EditorLog.Error("compile failed:\n" + job.Output);
            Status = "Compile failed";
            EditorWindow.GetWindow<ConsolePanel>(); // hatalar gorunur olsun
            return;
        }
        bool wasPlaying = PlayMode.State != PlayState.Editing;
        App.ApplyCompiledGame(job);
        if (wasPlaying)
            PlayMode.Play(); // taze koda taze oyun (runtime durum zaten reload'da olur)
        Status = "";
        EditorLog.Info($"code reloaded ({job.Scripts.Count} scripts)");
    }

// Proje acilisinda: tum AtlasGroup asset'leri paketlenir.
    public static void BuildAll()
    {
        foreach (var b in _built)
            Teardown(b);
        _built.Clear();
        SpriteTable.Clear();
        var assets = App.Assets;
        if (assets == null)
            return;
        foreach (var kv in assets.AllAssets)
        {
            if (!kv.Key.EndsWith(".asset", StringComparison.OrdinalIgnoreCase))
                continue;
            string full = System.IO.Path.Combine(assets.Root, kv.Key);
            if (ObjectSerializer.TypeNameOf(full) != nameof(AtlasGroup))
                continue;
            var g = ObjectSerializer.Load<AtlasGroup>(full, assets);
            Pack(kv.Key, g);
        }
    }

// png/grup degisti: bir sonraki uygun frame'de yeniden paketle (async yukler
    // inince — RepackPending Tick'ten cagrilir).
    public static void MarkDirtyByMember(string relPng)
    {
        foreach (var b in _built)
            if (IsMember(b.Group, relPng))
                _repack.Add(b.AssetPath);
    }

public static bool IsAtlasGroupAsset(string fullPath)
        => fullPath.EndsWith(".asset", StringComparison.OrdinalIgnoreCase)
        && ObjectSerializer.TypeNameOf(fullPath) == nameof(AtlasGroup);

public static void Tick()
    {
        if (_repack.Count == 0 || App.Assets == null || App.Assets.PendingCount > 0)
            return; // tum async yukler insin ki taze pikseller paketlensin
        var list = new List<string>(_repack);
        _repack.Clear();
        foreach (var rel in list)
        {
            string full = System.IO.Path.Combine(App.Assets.Root, rel);
            if (!System.IO.File.Exists(full))
            {
                Remove(rel);
                continue;
            }
            var g = ObjectSerializer.Load<AtlasGroup>(full, App.Assets);
            Pack(rel, g);
        }
    }

static bool IsMember(AtlasGroup g, string rel)
    {
        string ext = System.IO.Path.GetExtension(rel).ToLowerInvariant();
        if (ext is not (".png" or ".jpg" or ".jpeg"))
            return false;
        foreach (var f in g.folders)
        {
            if (string.IsNullOrEmpty(f))
                continue;
            string prefix = f.Replace('\\', '/').TrimEnd('/') + "/";
            if (rel.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                return true;
        }
        return false;
    }

static void Pack(string assetPath, AtlasGroup g)
    {
        var assets = App.Assets;
        Remove(assetPath); // eski kayitlar dusur (varsa)

        var members = new List<string>();
        foreach (var kv in assets.AllAssets)
            if (IsMember(g, kv.Key))
                members.Add(kv.Key);
        members.Sort(StringComparer.OrdinalIgnoreCase); // deterministik yerlesim
        if (members.Count == 0)
            return;

        // Kaynaklari yukle ve pikseller inene kadar pompala (editor: kabul edilebilir).
        var texs = new List<Texture>();
        foreach (var m in members)
            texs.Add(assets.LoadTexture(m));
        for (int guard = 0; guard < 2000 && assets.PendingCount > 0; guard++)
        {
            assets.Tick(64);
            System.Threading.Thread.Sleep(1);
        }

        // Shelf pack: yukseklige gore sirali raflar. Alan yetene kadar boyut ikilenir.
        int pad = Math.Max(0, g.padding);
        var order = new List<int>();
        for (int i = 0; i < texs.Count; i++)
            order.Add(i);
        order.Sort((a, b) => texs[b].Height.CompareTo(texs[a].Height));

        int size = 256;
        int[] px = null, py = null;
        while (true)
        {
            px = new int[texs.Count];
            py = new int[texs.Count];
            if (TryPlace(texs, order, size, pad, px, py))
                break;
            size *= 2;
            if (size > Math.Max(256, g.maxSize))
            {
                EditorLog.Error($"atlas '{assetPath}' exceeds maxSize {g.maxSize} ({members.Count} images)");
                return;
            }
        }

        var atlas = Texture.FromColor(size, size, new Color(0, 0, 0, 0));
        atlas.Persistent = true;
        atlas.Name = "atlas:" + assetPath;
        var built = new Built { AssetPath = assetPath, Group = g, Atlas = atlas };
        for (int i = 0; i < texs.Count; i++)
        {
            atlas.BlitFrom(texs[i], px[i], py[i]);
            SpriteTable.Register(members[i], new SpriteTable.Entry
            {
                Atlas = atlas,
                FrameX = px[i],
                FrameY = py[i],
                DrawW = texs[i].Width,
                DrawH = texs[i].Height,
                OrigW = texs[i].Width,
                OrigH = texs[i].Height,
            });
            built.Members.Add(members[i]);
        }
        _built.Add(built);
        EditorLog.Info($"atlas packed: {assetPath} ({members.Count} sprites, {size}x{size})");
    }

static bool TryPlace(List<Texture> texs, List<int> order, int size, int pad, int[] px, int[] py)
    {
        int x = pad, y = pad, shelfH = 0;
        foreach (int i in order)
        {
            int w = texs[i].Width, h = texs[i].Height;
            if (w + pad * 2 > size || h + pad * 2 > size)
                return false;
            if (x + w + pad > size)
            {
                x = pad;
                y += shelfH + pad;
                shelfH = 0;
            }
            if (y + h + pad > size)
                return false;
            px[i] = x;
            py[i] = y;
            x += w + pad;
            shelfH = Math.Max(shelfH, h);
        }
        return true;
    }

static void Remove(string assetPath)
    {
        for (int i = _built.Count - 1; i >= 0; i--)
        {
            if (!string.Equals(_built[i].AssetPath, assetPath, StringComparison.OrdinalIgnoreCase))
                continue;
            Teardown(_built[i]);
            _built.RemoveAt(i);
        }
    }

static void Teardown(Built b)
    {
        foreach (var m in b.Members)
            SpriteTable.Unregister(m);
        b.Atlas?.Destroy();
    }

