            cb.Begin();
            Camera.EncodeAll(cameras, cb, fbw, fbh);
            GuiDock.EncodeWindows(cb);
#if DE_EDITOR
            // Replay pass'leri canli frame'den ONCE kosar; GUI ayni frame'de RT'yi okur.
