void Resize(int w, int h)
    {
        _retired ??= _rt;
        _rt = Texture.CreateRenderTarget(w, h);
        _rtW = w;
        _rtH = h;
    }

// Editor kamerasinin ortho'su: merkez + zoom -> dunya penceresi (y asagi).
    internal void ApplyEditorCam()
    {
        float halfW = _viewW * 0.5f / _zoom, halfH = _viewH * 0.5f / _zoom;
        Mat4.Ortho(_center.x - halfW, _center.x + halfW,
                   _center.y + halfH, _center.y - halfH, -1, 1, out EditorCam.ViewProj);
    }

Vec2 PanelToWorld(Vec2 p)
        => new Vec2(_center.x + (p.x - _viewW * 0.5f) / _zoom,
                    _center.y + (p.y - _viewH * 0.5f) / _zoom);

Vec2 WorldToPanel(Vec2 w)
        => new Vec2(_viewW * 0.5f + (w.x - _center.x) * _zoom,
                    _viewH * 0.5f + (w.y - _center.y) * _zoom);

// Unity F / cift tik: kamerayi objeye ortala, boyutuna gore zoom'u sigdir
    // (cocuklarin sprite'lari dahil kaba dunya-bbox; boyutsuz objede zoom korunur).
    public void FocusOn(int docId)
    {
        var es = App.EditScene;
        var live = es?.Live(docId);
        if (live == null)
            return;
        Vec3 wp = live.transform.position;
        _center = new Vec2(wp.x, wp.y);
        float ext = BoundsExtent(es, docId);
        if (ext > 0.5f)
            _zoom = Math.Clamp(MathF.Min(_viewW, _viewH) * 0.4f / ext, 0.05f, 40f);
    }

// Objenin + alt agacinin merkezden en uzak sprite kenari (yaklasik yaricap).
    static float BoundsExtent(EditorScene es, int rootId)
    {
        var root = es.Live(rootId);
        if (root == null)
            return 0f;
        Vec3 c = root.transform.position;
        float ext = 0f;
        foreach (var g in es.Doc.Objects)
        {
            if (g.Id != rootId && !IsUnder(es.Doc, g, rootId))
                continue;
            var live = es.Live(g.Id);
            var sr = live?.GetComponent<SpriteRenderer>();
            if (sr == null)
                continue;
            ref var m = ref live.transform._getWorldMatrix();
            // dunya-uzayi yari boyut: matris kolon uzunluklariyla olcek dahil
            float sx = MathF.Sqrt(m.m[0] * m.m[0] + m.m[1] * m.m[1]) * sr.Width * 0.5f;
            float sy = MathF.Sqrt(m.m[4] * m.m[4] + m.m[5] * m.m[5]) * sr.Height * 0.5f;
            float d = MathF.Sqrt((m.m[12] - c.x) * (m.m[12] - c.x) + (m.m[13] - c.y) * (m.m[13] - c.y));
            ext = MathF.Max(ext, d + MathF.Max(sx, sy));
        }
        return ext;
    }

static bool IsUnder(SceneDoc doc, SceneDoc.GoDoc g, int rootId)
    {
        int cur = g.Parent, guard = 0;
        while (cur != 0 && guard++ < 256)
        {
            if (cur == rootId)
                return true;
            SceneDoc.GoDoc p = null;
            foreach (var o in doc.Objects)
                if (o.Id == cur) { p = o; break; }
            cur = p?.Parent ?? 0;
        }
        return false;
    }

protected override void OnGui()
    {
        var vis = GuiClip.VisibleRect;
        var ev = Event.Current;

        if (Gui.Button(new Rect(4, 4, 36, 20), "1:1"))
            _zoom = 1f;
        if (Gui.Button(new Rect(44, 4, 36, 20), "Fit"))
            FitGameFrame();
        if (Gui.Button(new Rect(92, 4, 46, 20), _tool == Tool.Move ? "Move*" : "Move"))
            _tool = Tool.Move;
        if (Gui.Button(new Rect(142, 4, 58, 20), _tool == Tool.Rotate ? "Rotate*" : "Rotate"))
            _tool = Tool.Rotate;
        if (Gui.Button(new Rect(204, 4, 50, 20), _tool == Tool.Scale ? "Scale*" : "Scale"))
            _tool = Tool.Scale;

        // Unity W/E/R kisayollari (textfield odagi yokken).
        if (ev.Type == EventType.KeyDown && GuiUtility.KeyboardControl == 0)
        {
            if (ev.KeyCode == GLFWConst.KEY_W) { _tool = Tool.Move; ev.Use(); }
            else if (ev.KeyCode == GLFWConst.KEY_E) { _tool = Tool.Rotate; ev.Use(); }
            else if (ev.KeyCode == GLFWConst.KEY_R) { _tool = Tool.Scale; ev.Use(); }
        }

        if (ev.Type == EventType.Repaint && vis.width >= 8 && vis.height >= 8)
        {
            _seen = true;
            _viewW = vis.width;
            _viewH = vis.height;
            float s = Gui.Scale > 0 ? Gui.Scale : 1f;
            int w = Math.Max(8, (int)(vis.width * s));
            int h = Math.Max(8, (int)(vis.height * s));
            if (w != _rtW || h != _rtH)
                Resize(w, h); // eski RT BeginFrame'de olur; hedef encode oncesi baglanir
            GuiRenderer.DrawTexture(new Rect(0, 0, vis.width, vis.height), _rt);
        }

        DoGizmoAndSelect(vis, ev); // pan'den ONCE: tiklama onceligi

        int id = GuiUtility.GetControlID(_panHash, FocusType.Passive);
        switch (ev.GetTypeForControl(id))
        {
            case EventType.MouseDown:
                if (vis.Contains(ev.MousePosition))
                {
                    GuiUtility.HotControl = id;
                    ev.Use();
                }
                break;
            case EventType.MouseDrag:
                if (GuiUtility.HotControl == id)
                {
                    _center.x -= ev.Delta.x / _zoom;
                    _center.y -= ev.Delta.y / _zoom;
                    ev.Use();
                }
                break;
            case EventType.MouseUp:
                if (GuiUtility.HotControl == id)
                {
                    GuiUtility.HotControl = 0;
                    ev.Use();
                }
                break;
            case EventType.ScrollWheel:
                if (vis.Contains(ev.MousePosition))
                {
                    // Imlec merkezli zoom: imlecin altindaki dunya noktasi sabit kalir.
                    Vec2 before = PanelToWorld(ev.MousePosition);
                    _zoom = Math.Clamp(_zoom * MathF.Pow(1.1f, ev.Delta.y), 0.05f, 40f);
                    Vec2 after = PanelToWorld(ev.MousePosition);
                    _center.x += before.x - after.x;
                    _center.y += before.y - after.y;
                    ev.Use();
                }
                break;
        }

        if (ev.Type == EventType.Repaint)
        {
            DrawGameFrame();
            // Proje panelinden PREFAB birakma: imlecin dunya konumuna instance
            // (kabul karari importer tipinden — dosya tipi hardcode edilmez).
            if (DragDrop.Kind == DragDrop.Payload.Asset
                && AssetDatabase.ImportTypeOf(DragDrop.AssetPath) == typeof(Prefab)
                && vis.Contains(ev.MousePosition))
            {
                var wp = PanelToWorld(ev.MousePosition);
                string guid = DragDrop.AssetGuid;
                GuiRenderer.DrawRect(new Rect(ev.MousePosition.x - 4, ev.MousePosition.y - 4, 8, 8),
                    new Color(90, 170, 90, 220), 5);
                DragDrop.RegisterTarget(() =>
                {
                    var r = App.EditScene.InstantiatePrefab(guid, 0, new Vec3(wp.x, wp.y, 0f));
                    if (r != null)
                        Selection.DocId = r.Id;
                });
            }
        }
    }

void FitGameFrame()
    {
        float gw = GameOutput.ViewW, gh = GameOutput.ViewH;
        _center = new Vec2(gw * 0.5f, gh * 0.5f);
        _zoom = MathF.Min(_viewW / MathF.Max(1f, gw), _viewH / MathF.Max(1f, gh)) * 0.9f;
    }

// Oyun ekrani konturu: (0,0)-(gameW,gameH) dunya dikdortgeni panel uzayinda.
    void DrawGameFrame()
    {
        Vec2 a = WorldToPanel(default);
        Vec2 b = WorldToPanel(new Vec2(GameOutput.ViewW, GameOutput.ViewH));
        var c = new Color(120, 160, 255, 170);
        // layer 2: RT dokusu layer 1'de — kontur ustune cizilmeli.
        GuiRenderer.DrawRect(new Rect(a.x, a.y, b.x - a.x, 1), c, 2);
        GuiRenderer.DrawRect(new Rect(a.x, b.y, b.x - a.x, 1), c, 2);
        GuiRenderer.DrawRect(new Rect(a.x, a.y, 1, b.y - a.y), c, 2);
        GuiRenderer.DrawRect(new Rect(b.x, a.y, 1, b.y - a.y + 1), c, 2);
    }

// --- Secim + tasima/dondurme/olcek gizmolari ---

    enum Tool { }
MEMBERS

void DoGizmoAndSelect(in Rect vis, Event ev)
    {
        var es = App.EditScene;
        var selGo = es?.FindGo(Selection.DocId);
        var live = selGo != null ? es.Live(selGo.Id) : null;

        // Kontrol sayisi pass'ler arasi sabit kalmali: id'ler kosulsuz alinir.
        int idFree = GuiUtility.GetControlID(_gizmoHash, FocusType.Passive);
        int idX = GuiUtility.GetControlID(_gizmoHash, FocusType.Passive);
        int idY = GuiUtility.GetControlID(_gizmoHash, FocusType.Passive);
        int idSel = GuiUtility.GetControlID(_selectHash, FocusType.Passive);

        if (live != null)
        {
            Vec3 wp = live.transform.position;
            Vec2 c = WorldToPanel(new Vec2(wp.x, wp.y));
            // Isabet alanlari: kol cizgisi + uc isaretini kapsar (gorselden genis).
            // Rotate'te X/Y kollari yok (bos rect), halka ozel isabetle merkez kolunda.
            var freeRect = new Rect(c.x - 7, c.y - 7, 14, 14);
            var xRect = _tool == Tool.Rotate ? default : new Rect(c.x + 7, c.y - 6, AxisLen + 12, 12);
            var yRect = _tool == Tool.Rotate ? default : new Rect(c.x - 6, c.y + 7, 12, AxisLen + 12);
            HandleGizmo(idFree, freeRect, 0, c, selGo, live, ev);
            HandleGizmo(idX, xRect, 1, c, selGo, live, ev);
            HandleGizmo(idY, yRect, 2, c, selGo, live, ev);
            if (ev.Type == EventType.Repaint)
            {
                _hoverAxis = _hotAxis >= 0 ? _hotAxis
                    : HitAxis(freeRect, xRect, yRect, c, ev.MousePosition);
                if (_hoverAxis >= 0)
                    GuiCursorManager.Request(CursorFor(_hoverAxis));
                DrawGizmo(live, c);
            }
        }

        // Tikla-sec (sol tus): gizmo almadiysa. Ctrl = coklu toggle. Bos tik secimi
        // birakir, event kullanilmaz — pan kontrolu devralir.
        if (ev.GetTypeForControl(idSel) == EventType.MouseDown && ev.Button == 0
            && vis.Contains(ev.MousePosition))
        {
            int hit = HitTest(PanelToWorld(ev.MousePosition));
            bool ctrl = (ev.Modifiers & EventModifiers.Control) != 0;
            if (hit != 0)
            {
                if (ctrl)
                    Selection.Toggle(hit);
                else
                    Selection.DocId = hit;
                ev.Use();
            }
            else if (!ctrl)
            {
                Selection.Clear();
            }
        }
    }

GuiCursor CursorFor(int axis) => _tool switch
    {
        Tool.Rotate => GuiCursor.Hand,
        _ => axis switch { 1 => GuiCursor.ResizeH, 2 => GuiCursor.ResizeV, _ => GuiCursor.ResizeAll },
    };

// Imlec hangi kolun ustunde: merkez > halka > X > Y oncelik sirasi.
    int HitAxis(in Rect freeRect, in Rect xRect, in Rect yRect, Vec2 c, Vec2 m)
    {
        if (_tool == Tool.Rotate)
        {
            if (freeRect.Contains(m))
                return 0;
            return RingHit(c, m) ? 0 : -1;
        }
        return freeRect.Contains(m) ? 0 : xRect.Contains(m) ? 1 : yRect.Contains(m) ? 2 : -1;
    }

static bool RingHit(Vec2 c, Vec2 m)
    {
        float dx = m.x - c.x, dy = m.y - c.y;
        float d = MathF.Sqrt(dx * dx + dy * dy);
        return d >= RingR - RingBand && d <= RingR + RingBand;
    }

void HandleGizmo(int id, in Rect r, int axis, Vec2 c, SceneDoc.GoDoc g, GameObject live, Event ev)
    {
        switch (ev.GetTypeForControl(id))
        {
            case EventType.MouseDown:
                bool hit = _tool == Tool.Rotate && axis == 0
                    ? r.Contains(ev.MousePosition) || RingHit(c, ev.MousePosition)
                    : r.width > 0 && r.Contains(ev.MousePosition);
                if (ev.Button == 0 && hit)
                {
                    GuiUtility.HotControl = id;
                    _hotAxis = axis;
                    _dragStartMouse = ev.MousePosition;
                    _gizmoCenter = c;
                    _dragStartPos = g.Pos;
                    _dragStartRot = g.Rot;
                    _dragStartScale = g.Scale;
                    CaptureMultiStart(); // tasima tum secime uygulanir
                    ev.Use();
                }
                break;
            case EventType.MouseDrag:
                if (GuiUtility.HotControl == id)
                {
                    ApplyDrag(axis, g, live, ev);
                    ev.Use();
                }
                break;
            case EventType.MouseUp:
                if (GuiUtility.HotControl == id)
                {
                    GuiUtility.HotControl = 0;
                    _hotAxis = -1;
                    ev.Use();
                }
                break;
        }
    }

// Kumulatif drag (baslangictan) — ara frame kaybi birikmez. Hepsi SetTransform
    // bogazından: doc+canli+undo (coalesced).
    readonly List<(SceneDoc.GoDoc G, Vec3 StartPos)> _multiStart = new();

void CaptureMultiStart()
    {
        _multiStart.Clear();
        var es = App.EditScene;
        foreach (int sid in Selection.Ids)
        {
            var sg = es.FindGo(sid);
            if (sg != null)
                _multiStart.Add((sg, sg.Pos));
        }
    }

void ApplyDrag(int axis, SceneDoc.GoDoc g, GameObject live, Event ev)
    {
        switch (_tool)
        {
            case Tool.Move:
                {
                    var d = new Vec2((ev.MousePosition.x - _dragStartMouse.x) / _zoom,
                                     (ev.MousePosition.y - _dragStartMouse.y) / _zoom);
                    if (axis == 1) d.y = 0;
                    else if (axis == 2) d.x = 0;
                    // Tasima TUM secime uygulanir (her obje kendi parent uzayinda).
                    var es = App.EditScene;
                    for (int i = 0; i < _multiStart.Count; i++)
                    {
                        var (sg, start) = _multiStart[i];
                        var slive = es.Live(sg.Id);
                        if (slive == null)
                            continue;
                        Vec2 ld = WorldDeltaToParentLocal(slive, d);
                        es.SetTransform(sg, new Vec3(start.x + ld.x, start.y + ld.y, start.z), sg.Rot, sg.Scale);
                    }
                    break;
                }
            case Tool.Rotate:
                {
                    // Merkez etrafinda aci farki; 2D'de tum donusler z ekseninde —
                    // parent'li objede de lokal delta = ekran delta'si.
                    float a0 = MathF.Atan2(_dragStartMouse.y - _gizmoCenter.y, _dragStartMouse.x - _gizmoCenter.x);
                    float a1 = MathF.Atan2(ev.MousePosition.y - _gizmoCenter.y, ev.MousePosition.x - _gizmoCenter.x);
                    float deg = (a1 - a0) * (180f / MathF.PI);
                    if ((ev.Modifiers & EventModifiers.Shift) != 0)
                        deg = MathF.Round(deg / 15f) * 15f; // Shift: 15 derece snap
                    App.EditScene.SetTransform(g, g.Pos,
                        new Vec3(_dragStartRot.x, _dragStartRot.y, _dragStartRot.z + deg), g.Scale);
                    break;
                }
            case Tool.Scale:
                {
                    float dx = (ev.MousePosition.x - _dragStartMouse.x) / 100f;
                    float dy = (ev.MousePosition.y - _dragStartMouse.y) / 100f;
                    Vec3 sc = _dragStartScale;
                    if (axis == 0)
                    {
                        float f = MathF.Max(0.01f, 1f + dx - dy); // sag/yukari = buyut
                        sc = new Vec3(_dragStartScale.x * f, _dragStartScale.y * f, _dragStartScale.z);
                    }
                    else if (axis == 1)
                    {
                        sc.x = _dragStartScale.x * MathF.Max(0.01f, 1f + dx);
                    }
                    else
                    {
                        sc.y = _dragStartScale.y * MathF.Max(0.01f, 1f + dy);
                    }
                    App.EditScene.SetTransform(g, g.Pos, g.Rot, sc);
                    break;
                }
        }
    }

// Dunya deltasi -> parent-lokal delta (GoDoc.Pos lokaldir).
    static Vec2 WorldDeltaToParentLocal(GameObject live, Vec2 d)
    {
        var p = live.transform.parent;
        if (p == null)
            return d;
        ref var m = ref p._getWorldMatrix();
        float a = m.m[0], b = m.m[1], c = m.m[4], e = m.m[5];
        float det = a * e - c * b;
        if (MathF.Abs(det) < 1e-8f)
            return d;
        return new Vec2((e * d.x - c * d.y) / det, (-b * d.x + a * d.y) / det);
    }

// Dunya noktasindaki en ustteki (doc sirasinda sonuncu) sprite'in docId'si; 0 = yok.
    static int HitTest(Vec2 world)
    {
        var es = App.EditScene;
        if (es == null)
            return 0;
        int best = 0;
        var objs = es.Doc.Objects;
        for (int i = 0; i < objs.Count; i++)
        {
            var g = objs[i];
            var live = es.Live(g.Id);
            if (live == null || !live.activeInHierarchy)
                continue;
            var sr = live.GetComponent<SpriteRenderer>();
            if (sr == null)
                continue;
            ref var m = ref live.transform._getWorldMatrix();
            float a = m.m[0], b = m.m[1], c = m.m[4], e = m.m[5];
            float det = a * e - c * b;
            if (MathF.Abs(det) < 1e-8f)
                continue;
            float dx = world.x - m.m[12], dy = world.y - m.m[13];
            float lx = (e * dx - c * dy) / det;
            float ly = (-b * dx + a * dy) / det;
            if (MathF.Abs(lx) <= sr.Width * 0.5f && MathF.Abs(ly) <= sr.Height * 0.5f)
                best = g.Id; // doc sirasi ~ cizim sirasi: sonuncu ustte
        }
        return best;
    }

// Kol rengi: aktif surukleme = sari (Unity), hover = acik ton, normal = eksen rengi.
    Color AxisColor(int axis, Color normal)
    {
        if (_hotAxis == axis)
            return new Color(255, 222, 60, 255);
        if (_hoverAxis == axis)
            return new Color((byte)Math.Min(255, normal.r + 50), (byte)Math.Min(255, normal.g + 50),
                (byte)Math.Min(255, normal.b + 50), 255);
        return normal;
    }

void DrawGizmo(GameObject live, Vec2 c)
    {
        // Braketler TUM secim icin: birincil parlak, digerleri soluk.
        var esb = App.EditScene;
        var ids = Selection.Ids;
        for (int i = 0; i < ids.Count; i++)
        {
            var slive = esb.Live(ids[i]);
            if (slive == null)
                continue;
            Vec3 swp = slive.transform.position;
            Vec2 sc2 = WorldToPanel(new Vec2(swp.x, swp.y));
            DrawSelectionBrackets(slive, sc2, ids[i] == Selection.DocId
                ? new Color(255, 150, 30, 235)
                : new Color(200, 130, 50, 140));
        }

        var shadow = new Color(0, 0, 0, 110);

        if (_tool == Tool.Rotate)
        {
            // Dondurme halkasi: nokta dizisi (z-donusu mavi, Unity gibi) + mevcut
            // aciyi gosteren isaretci.
            Color ring = AxisColor(0, new Color(90, 160, 245, 255));
            const int segs = 36;
            for (int i = 0; i < segs; i++)
            {
                float a = i * (MathF.PI * 2f / segs);
                float px = c.x + MathF.Cos(a) * RingR, py = c.y + MathF.Sin(a) * RingR;
                GuiRenderer.DrawRect(new Rect(px - 1.5f, py - 1.5f, 3f, 3f), ring, 4);
            }
            float ang = live.transform.eulerAngles.z * (MathF.PI / 180f);
            float mx = c.x + MathF.Cos(ang) * RingR, my = c.y + MathF.Sin(ang) * RingR;
            GuiRenderer.DrawDiamond(new Vec2(mx, my), 6.5f, shadow, 3);
            GuiRenderer.DrawDiamond(new Vec2(mx, my), 5f, new Color(255, 222, 60, 255), 4);
            GuiRenderer.DrawRect(new Rect(c.x - 2, c.y - 2, 4, 4), ring, 4);
            return;
        }

        Color xCol = AxisColor(1, new Color(230, 65, 60, 255));
        Color yCol = AxisColor(2, new Color(120, 205, 70, 255));
        float tipX = c.x + 8 + AxisLen;
        float tipY = c.y + 8 + AxisLen;

        // Kollar: golge + cizgi (Tasi ve Olcek ayni govde, uc isareti farkli).
        GuiRenderer.DrawRect(new Rect(c.x + 8, c.y - 2, AxisLen - 4, 4), shadow, 3);
        GuiRenderer.DrawRect(new Rect(c.x + 8, c.y - 1, AxisLen - 4, 2), xCol, 4);
        GuiRenderer.DrawRect(new Rect(c.x - 2, c.y + 8, 4, AxisLen - 4), shadow, 3);
        GuiRenderer.DrawRect(new Rect(c.x - 1, c.y + 8, 2, AxisLen - 4), yCol, 4);

        if (_tool == Tool.Move)
        {
            // Ok baslari (elmas).
            GuiRenderer.DrawDiamond(new Vec2(tipX, c.y), 7f, shadow, 3);
            GuiRenderer.DrawDiamond(new Vec2(tipX, c.y), 5.5f, xCol, 4);
            GuiRenderer.DrawDiamond(new Vec2(c.x, tipY), 7f, shadow, 3);
            GuiRenderer.DrawDiamond(new Vec2(c.x, tipY), 5.5f, yCol, 4);
        }
        else
        {
            // Olcek: kare uclar (Unity scale tutamaci).
            GuiRenderer.DrawRect(new Rect(tipX - 5.5f, c.y - 5.5f, 11, 11), shadow, 3);
            GuiRenderer.DrawRect(new Rect(tipX - 4.5f, c.y - 4.5f, 9, 9), xCol, 4);
            GuiRenderer.DrawRect(new Rect(c.x - 5.5f, tipY - 5.5f, 11, 11), shadow, 3);
            GuiRenderer.DrawRect(new Rect(c.x - 4.5f, tipY - 4.5f, 9, 9), yCol, 4);
        }

        // Merkez serbest kolu: koyu cerceve + yari saydam dolgu.
        Color fill = _hotAxis == 0 ? new Color(255, 222, 60, 210)
            : _hoverAxis == 0 ? new Color(255, 255, 255, 120)
            : new Color(255, 255, 255, 60);
        GuiRenderer.DrawRect(new Rect(c.x - 7, c.y - 7, 14, 14), new Color(20, 22, 28, 200), 3);
        GuiRenderer.DrawRect(new Rect(c.x - 6, c.y - 6, 12, 12), fill, 4);
    }

void DrawSelectionBrackets(GameObject live, Vec2 c, Color bcol)
    {
        // Secim vurgusu: sprite OBB koselerinde L-braketler (Unity bounds stili).
        var sr = live.GetComponent<SpriteRenderer>();
        if (sr == null)
            return;
        ref var m = ref live.transform._getWorldMatrix();
        float hw = sr.Width * 0.5f, hh = sr.Height * 0.5f;
        Span<Vec2> corners = stackalloc Vec2[4]
        {
            new Vec2(-hw, -hh), new Vec2(hw, -hh), new Vec2(hw, hh), new Vec2(-hw, hh),
        };
        const float arm = 9f, thick = 2f;
        for (int i = 0; i < 4; i++)
        {
            float wx = m.m[0] * corners[i].x + m.m[4] * corners[i].y + m.m[12];
            float wy = m.m[1] * corners[i].x + m.m[5] * corners[i].y + m.m[13];
            Vec2 pp = WorldToPanel(new Vec2(wx, wy));
            // Braket kollari kutu merkezine dogru bakar (panel uzayinda eksen-hizali).
            float sx = pp.x < c.x ? 1f : -1f;
            float sy = pp.y < c.y ? 1f : -1f;
            GuiRenderer.DrawRect(new Rect(sx > 0 ? pp.x : pp.x - arm, pp.y - thick * 0.5f, arm, thick), bcol, 3);
            GuiRenderer.DrawRect(new Rect(pp.x - thick * 0.5f, sy > 0 ? pp.y : pp.y - arm, thick, arm), bcol, 3);
        }
    }

public static int DocId
    {
        get => _ids.Count > 0 ? _ids[^1] : 0;
        set
