void TickPlay()
    {
        double now = GLFW.GetTime();
        _playTime += (float)(now - _lastTick);
        _lastTick = now;
        float dur = MathF.Max(0.0001f, _duration - TailPad);
        if (_playTime >= dur)
        {
            if (_loop) _playTime = 0f;
            else { _playTime = dur; _playing = false; }
        }
    }

