                    int hit = (row >= 0 && row < _tracks.Count)
                        ? HitTestItems(_tracks[row].Keys, ev.MousePosition, row * RowH - _vScroll + RowH * 0.5f)
                        : -1;
                    if (hit >= 0)
                        BeginItemInteraction(row, hit, id, ev);
                    else if (ev.ClickCount == 2 && row >= 0 && row < _tracks.Count)
