public static int Leaf(ReadOnlySpan<int> panelIds)
    {
        int ni = AllocNode();
        ref Node n = ref _nodes[ni];
        n.Type = TypeLeaf;
        n.TabCount = Math.Min(panelIds.Length, MaxTabsPerLeaf);
        for (int i = 0; i < n.TabCount; i++)
            _tabs[ni * MaxTabsPerLeaf + i] = panelIds[i];
