public static GuiFont FromMemory(byte[] ttf)
    {
        var font = new GuiFont();
        font._ttf = ttf; // raster yolu icin tutulur (glyph'ler ihtiyac aninda)
        byte[] atlas = new byte[AtlasSize * AtlasSize]; // bake sonrasi GC'ye birakilir
        float[] glyphData = new float[CharCount * 9];
        float[] metrics = new float[5];

        int baked;
        fixed (byte* pTtf = ttf)
        fixed (byte* pAtlas = atlas)
        fixed (float* pGlyphs = glyphData)
        fixed (short* pKern = font._kern)
        fixed (float* pMetrics = metrics)
        {
            baked = Sokol.FontBake(pTtf, pAtlas, AtlasSize, pGlyphs, pKern, pMetrics);
            if (baked <= 0)
                return null;
            font.Texture = Texture.FromAlpha(AtlasSize, AtlasSize, pAtlas);
        }

        for (int i = 0; i < CharCount; i++)
        {
            int o = i * 9;
            font._glyphs[i] = new Glyph
            {
                Advance = glyphData[o + 0],
                XOff = glyphData[o + 1],
                YOff = glyphData[o + 2],
                W = glyphData[o + 3],
                H = glyphData[o + 4],
                AtlasX = glyphData[o + 5],
                AtlasY = glyphData[o + 6],
            };
        }
        font.Ascent = metrics[0];
        font.Descent = metrics[1];
        font.LineHeight = metrics[2];
        font.KernScale = metrics[3];
        font.SdfSize = metrics[4];
        return font;
    }

// Codepoint -> glyph indeksi (kapsam disi -> '?').
    public static int GlyphIndex(char c)
    {
        int cp = c;
        if (cp < FirstChar || cp >= FirstChar + CharCount)
            cp = '?';
        return cp - FirstChar;
    }

// Cok satirli metin olcusu — RASTER advencelarla (cizimle birebir: tamsayi ilerleme).
    public Vec2 TextSize(ReadOnlySpan<char> text, float pixelHeight)
    {
        int px = PhysPx(pixelHeight);
        float inv = 1f / Scale();
        var vm = RasterVMetrics(px);
        float maxW = 0, w = 0;
        int lines = 1;
        for (int i = 0; i < text.Length; i++)
        {
            char c = text[i];
            if (c == '\n')
            {
                if (w > maxW) maxW = w;
                w = 0;
                lines++;
                continue;
            }
            w += MathF.Round(GetRasterGlyph(px, c).Advance);
        }
        if (w > maxW) maxW = w;
        return new Vec2(maxW * inv, lines * vm.y * inv);
    }

// --- RASTER (UI) YOLU: fontstash modeli. SDF kucuk puntoda camur; UI metni
    // GERCEK fiziksel piksel boyutunda rasterize edilir, dinamik atlasa ihtiyac
    // aninda eklenir (codepoint bazli — Turkce dahil, sabit aralik yok). ---

    public const int RasterAtlasSize = 1024;

public Texture RasterTexture
    {
        get
        {
            EnsureRasterAtlas();
            return _rTexture;
        }
    }

// x = ascent, y = satir ilerlemesi (fiziksel px, boyut basina bir kez).
    public Vec2 RasterVMetrics(int physPx)
    {
        if (_rMetrics.TryGetValue(physPx, out var m))
            return m;
        float* o3 = stackalloc float[3];
        fixed (byte* p = _ttf)
            Sokol.FontVMetrics(p, physPx, o3);
        m = new Vec2(MathF.Round(o3[0]), MathF.Round(o3[2]));
        _rMetrics[physPx] = m;
        return m;
    }

public RGlyph GetRasterGlyph(int physPx, char c)
    {
        long key = ((long)physPx << 32) | c;
        if (_rGlyphs.TryGetValue(key, out var g))
            return g;
        EnsureRasterAtlas();

        const int Cap = 160 * 160;
        _rScratch ??= new byte[Cap];
        float* met = stackalloc float[5];
        int ok;
        fixed (byte* pTtf = _ttf)
        fixed (byte* pBuf = _rScratch)
            ok = Sokol.FontGlyph(pTtf, physPx, c, pBuf, Cap, met);

        if (ok == 0 || (met[0] <= 0f && met[3] <= 0f))
        {
            // font glyph'i icermiyor: '?' fallback (kendisi '?' degilse).
            if (c != '?')
            {
                g = GetRasterGlyph(physPx, '?');
                _rGlyphs[key] = g;
                return g;
            }
            g = default;
            _rGlyphs[key] = g;
            return g;
        }

        int w = (int)met[3], h = (int)met[4];
        int ax = 0, ay = 0;
        if (w > 0 && h > 0)
        {
            if (_shelfX + w + 1 > RasterAtlasSize)
            {
                _shelfY += _shelfH + 1;
                _shelfX = 0;
                _shelfH = 0;
            }
            if (_shelfY + h + 1 > RasterAtlasSize)
            {
                // Atlas dolu (cok nadir): bastan basla, cache sifirla — glyph'ler yeniden dolar.
                _shelfX = 0; _shelfY = 0; _shelfH = 0;
                _rGlyphs.Clear();
                Array.Clear(_rAtlas);
            }
            ax = _shelfX;
            ay = _shelfY;
            for (int row = 0; row < h; row++)
                Array.Copy(_rScratch, row * w, _rAtlas, (ay + row) * RasterAtlasSize + ax, w);
            _shelfX += w + 1;
            if (h > _shelfH) _shelfH = h;
            _rDirty = true;
        }
        g = new RGlyph
        {
            Advance = met[0],
            X0 = met[1],
            Y0 = met[2],
            W = w,
            H = h,
            AtlasX = ax,
            AtlasY = ay,
        };
        _rGlyphs[key] = g;
        return g;
    }

void EnsureRasterAtlas()
    {
        if (_rAtlas != null)
            return;
        _rAtlas = new byte[RasterAtlasSize * RasterAtlasSize];
        _rTexture = Texture.CreateDynamicAlpha(RasterAtlasSize, RasterAtlasSize);
    }

// Frame'de BIR KEZ: kirliyse GPU'ya yukle (host tum GUI pass'lerinden sonra cagirir;
    // sokol dinamik image'i frame'de bir kez guncellemeye izin verir).
    public void FlushRasterAtlas()
    {
        if (!_rDirty || _rTexture == null || _lastUpload == Time.frameCount)
            return;
        fixed (byte* p = _rAtlas)
            _rTexture.UpdateAlpha(p);
        _rDirty = false;
        _lastUpload = Time.frameCount;
    }

// GUI surucusu: GuiInput kuyrugundaki event'leri Unity'nin cok-pass modeliyle
// kosar: her frame Layout -> (kuyruktaki input event'leri sirayla) -> Repaint.
// UI kodu (GuiFunc) her pass'te bastan cagrilir; kontrol sirasi sabit kalmalidir.
// Pencere GuiInput.Attach ile kaydedilmis olmalidir.
public sealed class GuiHost
{
}
MEMBERS
field Event _ev = new Event()
method Frame(IntPtr window, Rect screen, GuiFunc gui, float scale = 1f)
method Mul(Vec2 v, float s)
method RunPass(EventType type, Vec2 mouse, Vec2 delta, int button, int clickCount,
        int keyCode, char character, EventModifiers mods, Rect screen, GuiFunc gui)

// screen MANTIKSAL (point) uzaydadir; scale = pencerenin DPI olcegi.
    // UNITY MODELI: HER event pass'inden once ayri bir Layout pass'i kosulur —
    // bir input pass'inde degisen state (secim vb.) sonraki pass'in layout
    // cache'ini gecersiz kilamaz.
    public void Frame(IntPtr window, Rect screen, GuiFunc gui, float scale = 1f)
    {
        float inv = scale > 0 ? 1f / scale : 1f;
        Vec2 mouse = Mul(GuiInput.MousePos(window), inv);
        GuiCursorManager.BeginFrame();

        ReadOnlySpan<GuiInput.Queued> events = GuiInput.Events(window);
        for (int i = 0; i < events.Length; i++)
        {
            ref readonly GuiInput.Queued q = ref events[i];
            // Scroll delta'si tik sayisidir, DPI'dan bagimsiz — olceklenmez.
            Vec2 delta = q.Type == EventType.ScrollWheel ? q.Delta : Mul(q.Delta, inv);
            Vec2 m = Mul(q.Mouse, inv);
            RunPass(EventType.Layout, m, default, 0, 1, 0, '\0', EventModifiers.None, screen, gui);
            RunPass(q.Type, m, delta, q.Button, q.ClickCount, q.Key, q.Character, q.Mods, screen, gui);
            mouse = m;
        }
        GuiInput.Clear(window);

        RunPass(EventType.Layout, mouse, default, 0, 1, 0, '\0', EventModifiers.None, screen, gui);
        RunPass(EventType.Repaint, mouse, default, 0, 1, 0, '\0', EventModifiers.None, screen, gui);
        GuiCursorManager.Apply(window);
    }

void RunPass(EventType type, Vec2 mouse, Vec2 delta, int button, int clickCount,
        int keyCode, char character, EventModifiers mods, Rect screen, GuiFunc gui)
    {
        _ev.Set(type, mouse, delta, button, clickCount, keyCode, character, mods);
        GuiUtility.BeginPass(_ev, screen);
        GuiLayoutUtility.BeginPass(type, screen);
        gui();
        GuiLayoutUtility.EndPass(type);
    }

public static void Attach(IntPtr window)
    {
        for (int i = 0; i < MaxWindows; i++)
        {
            if (_slots[i].Used)
                continue;
            _slots[i] = new Slot { Window = window, Used = true, Mouse = new Vec2(-1000, -1000) };
            GLFW.SetMouseButtonCallback(window, (IntPtr)(delegate* unmanaged[Cdecl]<IntPtr, int, int, int, void>)&MouseButtonCb);
            GLFW.SetCursorPosCallback(window, (IntPtr)(delegate* unmanaged[Cdecl]<IntPtr, double, double, void>)&CursorCb);
            GLFW.SetScrollCallback(window, (IntPtr)(delegate* unmanaged[Cdecl]<IntPtr, double, double, void>)&ScrollCb);
            GLFW.SetKeyCallback(window, (IntPtr)(delegate* unmanaged[Cdecl]<IntPtr, int, int, int, int, void>)&KeyCb);
            GLFW.SetCharCallback(window, (IntPtr)(delegate* unmanaged[Cdecl]<IntPtr, uint, void>)&CharCb);
            return;
        }
        throw new InvalidOperationException("GuiInput: pencere slotu doldu");
    }

public static void Detach(IntPtr window)
    {
        int s = SlotOf(window);
        if (s >= 0)
            _slots[s].Used = false;
    }

public static Vec2 MousePos(IntPtr window)
    {
        int s = SlotOf(window);
        return s >= 0 ? _slots[s].Mouse : default;
    }

public static ReadOnlySpan<Queued> Events(IntPtr window)
    {
        int s = SlotOf(window);
        return s >= 0 ? _events.AsSpan(s * MaxEvents, _slots[s].Count) : default;
    }

public static void Clear(IntPtr window)
    {
        int s = SlotOf(window);
        if (s >= 0)
            _slots[s].Count = 0;
    }

static int SlotOf(IntPtr window)
    {
        for (int i = 0; i < MaxWindows; i++)
            if (_slots[i].Used && _slots[i].Window == window)
                return i;
        return -1;
    }

static void Enqueue(int slot, in Queued q, bool coalesce)
    {
        ref Slot s = ref _slots[slot];
        int baseIdx = slot * MaxEvents;
        if (coalesce && s.Count > 0 && _events[baseIdx + s.Count - 1].Type == q.Type)
        {
            _events[baseIdx + s.Count - 1] = q; // ardisik move/drag: sonuncusu yeter
            return;
        }
        if (s.Count == MaxEvents)
            return; // tasma: en eskiyi korumak daha guvenli, yenisini dusur
        _events[baseIdx + s.Count++] = q;
    }

static EventModifiers Mods(IntPtr w)
    {
        EventModifiers m = EventModifiers.None;
        if (GLFW.GetKey(w, GLFWConst.KEY_LEFT_SHIFT) == GLFWConst.PRESS || GLFW.GetKey(w, GLFWConst.KEY_RIGHT_SHIFT) == GLFWConst.PRESS)
            m |= EventModifiers.Shift;
        if (GLFW.GetKey(w, GLFWConst.KEY_LEFT_CONTROL) == GLFWConst.PRESS || GLFW.GetKey(w, GLFWConst.KEY_RIGHT_CONTROL) == GLFWConst.PRESS)
            m |= EventModifiers.Control;
        if (GLFW.GetKey(w, GLFWConst.KEY_LEFT_ALT) == GLFWConst.PRESS || GLFW.GetKey(w, GLFWConst.KEY_RIGHT_ALT) == GLFWConst.PRESS)
            m |= EventModifiers.Alt;
        return m;
    }

[UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    static void MouseButtonCb(IntPtr win, int button, int action, int mods)
    {
        int s = SlotOf(win);
        if (s < 0)
            return;
        Vec2 mouse = _slots[s].Mouse;
        bool down = action == GLFWConst.PRESS;
        int clicks = 1;
        if (down)
        {
            double now = GLFW.GetTime();
            float dx = mouse.x - _lastClickPos.x, dy = mouse.y - _lastClickPos.y;
            if (win == _lastClickWindow && now - _lastClickTime < 0.35 && dx * dx + dy * dy < 25f)
                _clickCount++;
            else
                _clickCount = 1;
            _lastClickTime = now;
            _lastClickPos = mouse;
            _lastClickWindow = win;
            clicks = _clickCount;
        }
        Enqueue(s, new Queued
        {
            Type = down ? EventType.MouseDown : EventType.MouseUp,
            Mouse = mouse,
            Button = button,
            ClickCount = clicks,
            Mods = Mods(win),
        }, coalesce: false);
    }

[UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    static void CursorCb(IntPtr win, double x, double y)
    {
        int s = SlotOf(win);
        if (s < 0)
            return;
        var mouse = new Vec2((float)x, (float)y);
        var delta = new Vec2(mouse.x - _slots[s].Mouse.x, mouse.y - _slots[s].Mouse.y);
        _slots[s].Mouse = mouse;
        bool anyDown = GLFW.GetMouseButton(win, 0) == GLFWConst.PRESS
            || GLFW.GetMouseButton(win, 1) == GLFWConst.PRESS
            || GLFW.GetMouseButton(win, 2) == GLFWConst.PRESS;
        Enqueue(s, new Queued
        {
            Type = anyDown ? EventType.MouseDrag : EventType.MouseMove,
            Mouse = mouse,
            Delta = delta,
            Mods = Mods(win),
        }, coalesce: true);
    }

[UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    static void ScrollCb(IntPtr win, double sx, double sy)
    {
        int s = SlotOf(win);
        if (s < 0)
            return;
        Enqueue(s, new Queued
        {
            Type = EventType.ScrollWheel,
            Mouse = _slots[s].Mouse,
            Delta = new Vec2((float)sx, (float)sy),
            Mods = Mods(win),
        }, coalesce: false);
    }

[UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    static void KeyCb(IntPtr win, int key, int scancode, int action, int mods)
    {
        int s = SlotOf(win);
        if (s < 0)
            return;
        if (action == GLFWConst.REPEAT)
            action = GLFWConst.PRESS; // basili tutma tekrar uretsin (backspace vb.)
        Enqueue(s, new Queued
        {
            Type = action == GLFWConst.PRESS ? EventType.KeyDown : EventType.KeyUp,
            Mouse = _slots[s].Mouse,
            Key = key,
            Mods = Mods(win),
        }, coalesce: false);
    }

[UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    static void CharCb(IntPtr win, uint codepoint)
    {
        int s = SlotOf(win);
        if (s < 0)
            return;
        Enqueue(s, new Queued
        {
            Type = EventType.TextInput,
            Mouse = _slots[s].Mouse,
            Character = codepoint <= char.MaxValue ? (char)codepoint : '\uFFFD',
            Mods = Mods(win),
        }, coalesce: false);
    }

