static void EnsureResources()
    {
        if (_material != null)
            return;
        _quad = Mesh.Quad();
        _material = new Material
        {
            MainTexture = Texture.FromColor(1, 1, new Color(255, 255, 255, 255)),
            SortMode = SortMode.Ui,
