        Buffer.MemoryCopy(cb.Ptr, _captured, _capturedCap, len);
        _capturedLen = len;
        StreamBytes = len;
        Walk();
        EnsureReplayTarget();
        Frozen = true;
        MaxDraws = DrawCount;
    }

