// --- Canli sahne → doc (bootstrap/kaydet) ---

    public static SceneDoc Capture(Scene scene, TypeCatalog catalog, AssetDatabase assets = null)
    {
        var doc = new SceneDoc { Name = scene.Name };
        // 1. gecis: id atamasi — ileri referanslar (henuz gezilmemis GO'ya) cozulebilsin.
        var ids = new Dictionary<GameObject, int>();
        int nextId = 1;
        for (int i = 0; i < scene.RootCount; i++)
            AssignIds(scene.GetRoot(i), ids, ref nextId);
        for (int i = 0; i < scene.RootCount; i++)
            CaptureGo(doc, catalog, scene.GetRoot(i), 0, ids, assets);
        return doc;
    }

static void AssignIds(GameObject go, Dictionary<GameObject, int> ids, ref int nextId)
    {
        ids[go] = nextId++;
        for (var t = go.transform.FirstChild; t != null; t = t.NextSibling)
            if (t._gameObject != null)
                AssignIds(t._gameObject, ids, ref nextId);
    }

// Prefab: tek alt agac — kok, doc icinde parent=0 olur.
    public static SceneDoc CaptureSubtree(GameObject root, TypeCatalog catalog, AssetDatabase assets = null)
    {
        var doc = new SceneDoc { Name = root.name };
        var ids = new Dictionary<GameObject, int>();
        int nextId = 1;
        AssignIds(root, ids, ref nextId);
        CaptureGo(doc, catalog, root, 0, ids, assets);
        return doc;
    }

static void CaptureGo(SceneDoc doc, TypeCatalog catalog, GameObject go, int parentId, Dictionary<GameObject, int> ids, AssetDatabase assets)
    {
        var g = new GoDoc
        {
            Id = ids[go],
            Parent = parentId,
            Name = go.name,
            Active = go.activeSelf,
            Pos = go.transform.localPosition,
            Rot = go.transform.localEulerAngles,
            Scale = go.transform.localScale,
        };
        doc.Objects.Add(g);

        int n = go.ComponentCount;
        for (int i = 0; i < n; i++)
        {
            var c = go.ComponentAt(i);
            if (c is Transform)
                continue; // transform GoDoc'ta (Unity da ayni: ozel serilesir)
            var entry = catalog.Find(c.GetType());
            if (entry == null)
                continue;
            var cd = new CompDoc { Type = entry.Name, Enabled = c._enabled };
            foreach (var f in entry.Schema)
                cd.Props.Add(new(f.Name, SerializedType.WriteField(c, f,
                    target => GoRefValue(target, ids),
                    target => CompRefValue(target, ids),
                    assets)));
            g.Components.Add(cd);
        }

        for (var t = go.transform.FirstChild; t != null; t = t.NextSibling)
            if (t._gameObject != null)
                CaptureGo(doc, catalog, t._gameObject, g.Id, ids, assets);
    }

internal static string GoRefValue(GameObject target, Dictionary<GameObject, int> ids)
        => target != null && ids.TryGetValue(target, out int id)
            ? id.ToString(CultureInfo.InvariantCulture) : "";

// "goId:TipAdi:ayniTiptenKacinci" — sahne disi referans kaydedilemez (bos).
    internal static string CompRefValue(Component c, Dictionary<GameObject, int> ids)
    {
        if (c == null || c._gameObject == null || !ids.TryGetValue(c._gameObject, out int id))
            return "";
        var go = c._gameObject;
        int idx = 0;
        for (int i = 0; i < go.ComponentCount; i++)
        {
            var o = go.ComponentAt(i);
            if (o == c)
                break;
            if (o.GetType() == c.GetType())
                idx++;
        }
        return id + ":" + c.GetType().Name + ":" + idx;
    }

// --- Doc → canli sahne ---

    // Unity deserialize sirasi: alanlar Awake'ten ONCE yazilir. Bu yuzden
    // component'ler aktivasyonsuz eklenir, tum alanlar yazildiktan sonra
    // topluca aktive edilir (Awake taze degerleri gorur).
    public void InstantiateInto(Scene scene, TypeCatalog catalog, AssetDatabase assets)
    {
        scene.Catalog = catalog;
        Scene.SetActive(scene); // new GameObject bu sahneye dogar
        Spawn(null, catalog, assets);
    }

// Doc'u AKTIF sahneye (istege bagli parent altina) kurar; ilk kok GO'yu dondurur.
    // Prefab spawn da sahne yukleme de ayni yol: referans cozumu + gec aktivasyon.
    // liveMap verilirse docId -> canli GO eslesmesi doldurulur (editor patch'leri icin).
    public GameObject Spawn(Transform parent, TypeCatalog catalog, AssetDatabase assets,
        Dictionary<int, GameObject> liveMap = null)
    {
        GameObject first = null;
        var byId = liveMap ?? new Dictionary<int, GameObject>();
        byId.Clear();
        // Referanslar TUM nesneler dogduktan sonra cozulur (ileri referans serbest).
        // Liste/ic-ice nesne icindeki referanslar da ayni kuyruga girer (closure set).
        var deferred = new List<(SerializedType.Kind kind, string val, Action<object> set)>();
        void Sink(SerializedType.Kind kind, string val, Action<object> set) => deferred.Add((kind, val, set));

        // 1. gecis: tum GO'lar dogar — parent cozumu liste sirasindan BAGIMSIZ
        // (reparent edilmis doc'ta cocuk parent'tan once gelebilir).
        foreach (var g in Objects)
        {
            var go = new GameObject(g.Name);
            byId[g.Id] = go;
            first ??= go;
        }

        foreach (var g in Objects)
        {
            var go = byId[g.Id];
            if (g.Parent != 0 && byId.TryGetValue(g.Parent, out var p))
                go.transform.SetParent(p.transform, false);
            else if (parent != null)
                go.transform.SetParent(parent, false);
            go.transform.localPosition = g.Pos;
            go.transform.localEulerAngles = g.Rot;
            go.transform.localScale = g.Scale;

            foreach (var cd in g.Components)
            {
                var entry = catalog.Find(cd.Type);
                if (entry == null)
                    continue; // bilinmeyen tip: sessiz atla (eski sahne + silinmis component)
                var c = go.AddComponentRaw(entry);
                c._enabled = cd.Enabled;
                foreach (var kv in cd.Props)
                {
                    var f = SerializedType.Find(entry.Schema, kv.Key);
                    if (f != null)
                        SerializedType.ReadField(c, f, kv.Value, assets, Sink);
                }
            }
            if (!g.Active)
                go.SetActive(false);
        }
        foreach (var (kind, val, set) in deferred)
            set(ResolveRef(kind, val, byId));
        foreach (var g in Objects)
            byId[g.Id].ActivateComponentsNow();
        return first;
    }

static object ResolveRef(SerializedType.Kind kind, string val, Dictionary<int, GameObject> byId)
    {
        if (string.IsNullOrEmpty(val))
            return null;
        if (kind == SerializedType.Kind.GoRef)
            return int.TryParse(val, out int goId) && byId.TryGetValue(goId, out var go) ? go : null;
        var p = val.Split(':');
        if (p.Length != 3 || !int.TryParse(p[0], out int id) || !byId.TryGetValue(id, out var target))
            return null;
        if (!int.TryParse(p[2], out int wantIdx))
            return null;
        int idx = 0;
        for (int i = 0; i < target.ComponentCount; i++)
        {
            var c = target.ComponentAt(i);
            if (c.GetType().Name != p[1])
                continue;
            if (idx == wantIdx)
                return c;
            idx++;
        }
        return null;
    }

// catalog+assets verilirse prefab instance'lari DELTAYA sikistirilir (collapse):
    // expand-node'lar yazilmaz, kokte guid + ids esleme + override diff'i yazilir.
    public string ToYaml(TypeCatalog catalog, AssetDatabase assets)
    {
        bool collapse = catalog != null && assets != null;
        var root = DocNode.Map();
        root.Add("scene", DocNode.Scal(Name));
        var objects = DocNode.Seq();
        root.Add("objects", objects);
        foreach (var g in Objects)
        {
            if (collapse && g.IsPrefabChild)
                continue; // delta: expand-node diske yazilmaz
            var m = DocNode.Map();
            m.Add("id", DocNode.Scal(g.Id.ToString(CultureInfo.InvariantCulture)));
            m.Add("parent", DocNode.Scal(g.Parent.ToString(CultureInfo.InvariantCulture)));
            m.Add("name", DocNode.Scal(g.Name));
            if (!g.Active)
                m.Add("active", DocNode.Scal("false"));
            m.Add("pos", DocNode.Scal(V3(g.Pos)));
            m.Add("rot", DocNode.Scal(V3(g.Rot)));
            m.Add("scale", DocNode.Scal(V3(g.Scale)));
            if (collapse && g.IsPrefabRoot)
            {
                WritePrefabRecord(m, g, catalog, assets);
                objects.Items.Add(m);
                continue;
            }
            if (g.Components.Count > 0)
            {
                var comps = DocNode.Seq();
                m.Add("components", comps);
                foreach (var cd in g.Components)
                    comps.Items.Add(CompToNode(cd));
            }
            objects.Items.Add(m);
        }
        return Yaml.Write(root);
    }

static DocNode CompToNode(CompDoc cd)
    {
        var cm = DocNode.Map();
        cm.Add("type", DocNode.Scal(cd.Type));
        if (!cd.Enabled)
            cm.Add("enabled", DocNode.Scal("false"));
        foreach (var kv in cd.Props)
            cm.Add(kv.Key, kv.Value);
        return cm;
    }

public static SceneDoc Parse(string text)
    {
        var doc = new SceneDoc();
        var root = Yaml.Parse(text);
        doc.Name = root.GetScalar("scene", "Main");
        var objects = root.Get("objects");
        if (objects?.Items == null)
            return doc;
        foreach (var m in objects.Items)
        {
            if (!m.IsMap)
                continue;
            var g = new GoDoc
            {
                Id = ParseInt(m.GetScalar("id")),
                Parent = ParseInt(m.GetScalar("parent")),
                Name = m.GetScalar("name", "GameObject"),
                Active = m.GetScalar("active", "true") != "false",
                Pos = SerializedType.ParseVec3(m.GetScalar("pos", "0 0 0")),
                Rot = SerializedType.ParseVec3(m.GetScalar("rot", "0 0 0")),
                Scale = SerializedType.ParseVec3(m.GetScalar("scale", "1 1 1")),
            };
            doc.Objects.Add(g);
            string prefab = m.GetScalar("prefab", null);
            if (!string.IsNullOrEmpty(prefab))
            {
                // Delta kaydi: ExpandPrefabs cagrilana kadar bosaltilmis instance koku.
                g.PrefabGuid = prefab;
                g.PrefabIds = ParseIdMap(m.GetScalar("prefabIds", ""));
                g.PrefabRemoved = ParseIdList(m.GetScalar("removed", ""));
                g.PendingOverrides = m.Get("overrides");
                continue; // component'ler prefab'dan gelir
            }
            var comps = m.Get("components");
            if (comps?.Items == null)
                continue;
            foreach (var cm in comps.Items)
                if (cm.IsMap)
                    g.Components.Add(CompFromNode(cm));
        }
        return doc;
    }

// Yaml comp haritasi -> CompDoc (Parse ve prefab addComp override'i ayni yolu kullanir).
    internal static CompDoc CompFromNode(DocNode cm)
    {
        var cd = new CompDoc
        {
            Type = cm.GetScalar("type"),
            Enabled = cm.GetScalar("enabled", "true") != "false",
        };
        foreach (var kv in cm.Fields)
            if (kv.Key != "type" && kv.Key != "enabled")
                cd.Props.Add(kv);
        return cd;
    }

static Dictionary<int, int> ParseIdMap(string s)
    {
        var map = new Dictionary<int, int>();
        foreach (var pair in s.Split(' ', StringSplitOptions.RemoveEmptyEntries))
        {
            int c = pair.IndexOf(':');
            if (c > 0 && int.TryParse(pair.Substring(0, c), out int k) && int.TryParse(pair.Substring(c + 1), out int v))
                map[k] = v;
        }
        return map;
    }

static List<int> ParseIdList(string s)
    {
        var list = new List<int>();
        foreach (var part in s.Split(' ', StringSplitOptions.RemoveEmptyEntries))
            if (int.TryParse(part, out int v))
                list.Add(v);
        return list;
    }

// Yuklemeden sonra bir kez: tum instance kayitlarini acar.
    public void ExpandPrefabs(TypeCatalog catalog, AssetDatabase assets)
    {
        // Expand liste buyutur: kayitlarin anlik kopyasi uzerinden.
        var roots = new List<GoDoc>();
        foreach (var g in Objects)
            if (g.IsPrefabRoot && g.PrefabLocalId == 0)
                roots.Add(g);
        foreach (var r in roots)
            ExpandInstance(r, catalog, assets);
    }

// Tek instance'i acar: prefab dogunu klonlar, id esler, override'lari uygular.
    public void ExpandInstance(GoDoc root, TypeCatalog catalog, AssetDatabase assets)
    {
        var prefab = assets?.LoadPrefab(root.PrefabGuid)?.Doc;
        if (prefab == null)
            return; // missing prefab: delta oldugu gibi kalir (kaydedince kaybolmaz)
        root.PrefabIds ??= new Dictionary<int, int>();
        root.PrefabRemoved ??= new List<int>();

        int nextId = 0;
        foreach (var g in Objects)
            if (g.Id > nextId)
                nextId = g.Id;
        foreach (var kv in root.PrefabIds)
            if (kv.Value > nextId)
                nextId = kv.Value;

        // 1. gecis: localId -> sceneId eslemesi (yeni prefab cocuklari yeni id alir).
        int prefabRootLocal = 0;
        foreach (var pl in prefab.Objects)
        {
            if (pl.Parent == 0)
                prefabRootLocal = pl.Id;
            if (IsRemovedWithAncestors(prefab, root, pl))
                continue;
            if (pl.Parent == 0)
                root.PrefabIds[pl.Id] = root.Id;
            else if (!root.PrefabIds.ContainsKey(pl.Id))
                root.PrefabIds[pl.Id] = ++nextId;
        }
        root.PrefabLocalId = prefabRootLocal;
        root.PrefabRootId = root.Id;

        // 2. gecis: node'lari uret (kok instance kaydiyla birlesir).
        int insertAt = Objects.IndexOf(root) + 1;
        foreach (var pl in prefab.Objects)
        {
            if (IsRemovedWithAncestors(prefab, root, pl))
                continue;
            GoDoc g;
            if (pl.Parent == 0)
            {
                g = root; // kok: transform/parent/ad instance'a ait, component'ler prefab'dan
                g.Components.Clear();
            }
            else
            {
                g = new GoDoc
                {
                    Id = root.PrefabIds[pl.Id],
                    Parent = root.PrefabIds.GetValueOrDefault(pl.Parent, root.Id),
                    Name = pl.Name,
                    Active = pl.Active,
                    Pos = pl.Pos,
                    Rot = pl.Rot,
                    Scale = pl.Scale,
                    PrefabLocalId = pl.Id,
                    PrefabRootId = root.Id,
                };
                Objects.Insert(insertAt++, g);
            }
            foreach (var cd in pl.Components)
            {
                var nc = new CompDoc { Type = cd.Type, Enabled = cd.Enabled };
                foreach (var kv in cd.Props)
                    nc.Props.Add(new(kv.Key, kv.Value.Clone()));
                RemapCompRefs(nc, catalog, root.PrefabIds); // prefab-ici ref -> sahne id
                g.Components.Add(nc);
            }
        }

        ApplyOverrides(root);
        root.PendingOverrides = null;
    }

static bool IsRemovedWithAncestors(SceneDoc prefab, GoDoc root, GoDoc pl)
    {
        int cur = pl.Id, guard = 0;
        while (cur != 0 && guard++ < 1000)
        {
            if (root.PrefabRemoved != null && root.PrefabRemoved.Contains(cur))
                return true;
            GoDoc p = null;
            foreach (var o in prefab.Objects)
                if (o.Id == cur) { p = o; break; }
            cur = p?.Parent ?? 0;
        }
        return false;
    }

// Prefab-ici Go/CompRef scalar'larini sahne id'lerine cevirir (sema uzerinden).
    static void RemapCompRefs(CompDoc cd, TypeCatalog catalog, Dictionary<int, int> map)
    {
        var entry = catalog?.Find(cd.Type);
        if (entry == null)
            return;
        foreach (var kv in cd.Props)
        {
            var f = SerializedType.Find(entry.Schema, kv.Key);
            if (f == null)
                continue;
            RemapValue(kv.Value, f, map);
        }
    }

// Bir serialized alan agacindaki tum sahne referanslarini verilen id uzayina cevirir.
    public static void RemapValue(DocNode node, SerializedType.FieldSchema field,
        Dictionary<int, int> map)
    {
        if (node == null)
            return;
        if (field.Kind is SerializedType.Kind.GoRef or SerializedType.Kind.CompRef)
        {
            node.Scalar = RemapRefScalar(node.Scalar, field.Kind, map);
            return;
        }
        if (field.Kind == SerializedType.Kind.List && node.Items != null)
        {
            if (field.ElementKind is SerializedType.Kind.GoRef or SerializedType.Kind.CompRef)
            {
                foreach (var item in node.Items)
                    item.Scalar = RemapRefScalar(item.Scalar, field.ElementKind, map);
            }
            else if (field.ElementKind == SerializedType.Kind.Object)
            {
                foreach (var item in node.Items)
                    RemapObject(item, field.Nested, map);
            }
            return;
        }
        if (field.Kind == SerializedType.Kind.Object)
            RemapObject(node, field.Nested, map);
    }

static void RemapObject(DocNode mapNode, SerializedType.FieldSchema[] schema,
        Dictionary<int, int> map)
    {
        if (mapNode?.Fields == null || schema == null)
            return;
        foreach (var pair in mapNode.Fields)
        {
            var field = SerializedType.Find(schema, pair.Key);
            if (field != null)
                RemapValue(pair.Value, field, map);
        }
    }

static string RemapRefScalar(string s, SerializedType.Kind kind, Dictionary<int, int> map)
    {
        if (string.IsNullOrEmpty(s))
            return s;
        if (kind == SerializedType.Kind.GoRef)
            return int.TryParse(s, out int id) && map.TryGetValue(id, out int sid)
                ? sid.ToString(CultureInfo.InvariantCulture) : s;
        int c = s.IndexOf(':');
        return c > 0 && int.TryParse(s.Substring(0, c), out int cid) && map.TryGetValue(cid, out int csid)
            ? csid + s.Substring(c) : s;
    }

void ApplyOverrides(GoDoc root)
    {
        var ovs = root.PendingOverrides;
        if (ovs?.Items == null)
            return;
        foreach (var o in ovs.Items)
        {
            if (!o.IsMap)
                continue;
            int local = int.TryParse(o.GetScalar("node"), out int l) ? l : 0;
            if (!root.PrefabIds.TryGetValue(local, out int sceneId))
                continue;
            var g = FindById(sceneId);
            if (g == null)
                continue;
            string comp = o.GetScalar("comp", null);
            string prop = o.GetScalar("prop");
            var value = o.Get("value");
            if (string.IsNullOrEmpty(comp))
            {
                switch (prop)
                {
                    case "name": g.Name = value?.Scalar ?? g.Name; break;
                    case "active": g.Active = value?.Scalar != "false"; break;
                    case "pos": g.Pos = SerializedType.ParseVec3(value?.Scalar ?? "0 0 0"); break;
                    case "rot": g.Rot = SerializedType.ParseVec3(value?.Scalar ?? "0 0 0"); break;
                    case "scale": g.Scale = SerializedType.ParseVec3(value?.Scalar ?? "1 1 1"); break;
                    case "addComp": // instance'a eklenen comp (ref'ler sahne uzayinda kayitli)
                        if (value != null && value.IsMap)
                            g.Components.Add(CompFromNode(value.Clone()));
                        break;
                }
                continue;
            }
            var cd = FindComp(g, comp);
            if (prop == "removeComp")
            {
                if (cd != null)
                    g.Components.Remove(cd);
                continue;
            }
            if (cd == null)
                continue;
            if (prop == "enabled")
            {
                cd.Enabled = value?.Scalar != "false";
                continue;
            }
            var clone = value?.Clone() ?? DocNode.Scal("");
            for (int i = 0; i < cd.Props.Count; i++)
            {
                if (cd.Props[i].Key == prop)
                {
                    cd.Props[i] = new(prop, clone);
                    goto next;
                }
            }
            cd.Props.Add(new(prop, clone));
        next:;
        }
    }

GoDoc FindById(int id)
    {
        foreach (var g in Objects)
            if (g.Id == id)
                return g;
        return null;
    }

// "Tip:idx" adresinden component (ayni tipten idx'inci).
    static CompDoc FindComp(GoDoc g, string address)
    {
        int c = address.LastIndexOf(':');
        string type = c > 0 ? address.Substring(0, c) : address;
        int want = c > 0 && int.TryParse(address.Substring(c + 1), out int w) ? w : 0;
        int idx = 0;
        foreach (var cd in g.Components)
        {
            if (cd.Type != type)
                continue;
            if (idx == want)
                return cd;
            idx++;
        }
        return null;
    }

// --- Collapse: kok kaydina guid + ids + removed + override diff'i yazar ---

    void WritePrefabRecord(DocNode m, GoDoc root, TypeCatalog catalog, AssetDatabase assets)
    {
        m.Add("prefab", DocNode.Scal(root.PrefabGuid));
        var sb = new StringBuilder();
        foreach (var kv in root.PrefabIds)
            sb.Append(kv.Key).Append(':').Append(kv.Value).Append(' ');
        m.Add("prefabIds", DocNode.Scal(sb.ToString().TrimEnd()));
        if (root.PrefabRemoved is { Count: > 0 })
            m.Add("removed", DocNode.Scal(string.Join(' ', root.PrefabRemoved)));
        var ovs = BuildOverrides(root, catalog, assets);
        if (ovs != null && ovs.Items.Count > 0)
            m.Add("overrides", ovs);
    }

// Instance'in TUM override'lari (yaml diff'i ile ayni; editor Overrides paneli de kullanir).
    // Donen seq ogeleri: {node, comp?, prop, value}. null = prefab kayip.
    public DocNode BuildOverrides(GoDoc root, TypeCatalog catalog, AssetDatabase assets)
    {
        var prefab = assets?.LoadPrefab(root.PrefabGuid)?.Doc;
        if (prefab == null)
            return null; // missing prefab: diff uretilemez, delta korunur
        var ovs = DocNode.Seq();

        foreach (var pl in prefab.Objects)
        {
            if (!root.PrefabIds.TryGetValue(pl.Id, out int sceneId))
                continue;
            var g = FindById(sceneId);
            if (g == null)
                continue;
            bool isRoot = g == root;
            // Kok transform/ad instance'a aittir (normal alanlarda yazildi) — diff yok.
            if (!isRoot)
            {
                if (g.Name != pl.Name)
                    AddOverride(ovs, pl.Id, null, "name", DocNode.Scal(g.Name));
                if (g.Active != pl.Active)
                    AddOverride(ovs, pl.Id, null, "active", DocNode.Scal(g.Active ? "true" : "false"));
                if (!SameV3(g.Pos, pl.Pos))
                    AddOverride(ovs, pl.Id, null, "pos", DocNode.Scal(V3(g.Pos)));
                if (!SameV3(g.Rot, pl.Rot))
                    AddOverride(ovs, pl.Id, null, "rot", DocNode.Scal(V3(g.Rot)));
                if (!SameV3(g.Scale, pl.Scale))
                    AddOverride(ovs, pl.Id, null, "scale", DocNode.Scal(V3(g.Scale)));
            }
            DiffComponents(ovs, pl, g, catalog, root.PrefabIds);
        }
        return ovs;
    }

void DiffComponents(DocNode ovs, GoDoc pl, GoDoc g, TypeCatalog catalog, Dictionary<int, int> map)
    {
        // Karsilastirma prefab'in REMAP EDILMIS klonu uzerinden: prefab-ici ref'ler
        // sahne id'lerine cevrilir ki degismemis ref esit ciksin.
        var occ = new Dictionary<string, int>();
        foreach (var pcd in pl.Components)
        {
            int idx = occ.GetValueOrDefault(pcd.Type);
            occ[pcd.Type] = idx + 1;
            string addr = pcd.Type + ":" + idx;
            var scd = FindComp(g, addr);
            if (scd == null)
            {
                AddOverride(ovs, pl.Id, addr, "removeComp", DocNode.Scal("true")); // instance'ta silinmis
                continue;
            }

            var refCmp = new CompDoc { Type = pcd.Type };
            foreach (var kv in pcd.Props)
                refCmp.Props.Add(new(kv.Key, kv.Value.Clone()));
            RemapCompRefs(refCmp, catalog, map);

            if (scd.Enabled != pcd.Enabled)
                AddOverride(ovs, pl.Id, addr, "enabled", DocNode.Scal(scd.Enabled ? "true" : "false"));
            foreach (var kv in scd.Props)
            {
                DocNode pv = null;
                foreach (var pkv in refCmp.Props)
                    if (pkv.Key == kv.Key) { pv = pkv.Value; break; }
                if (!DocNode.Equal(kv.Value, pv))
                    AddOverride(ovs, pl.Id, addr, kv.Key, kv.Value.Clone());
            }
        }
        // Instance'a EKLENEN comp'lar (prefab'da karsiligi yok): tam govde override'i.
        var sceneOcc = new Dictionary<string, int>();
        foreach (var scd in g.Components)
        {
            int idx = sceneOcc.GetValueOrDefault(scd.Type);
            sceneOcc[scd.Type] = idx + 1;
            if (idx < occ.GetValueOrDefault(scd.Type))
                continue; // prefab'daki karsiligi (ayni tip/sira) zaten diff'lendi
            AddOverride(ovs, pl.Id, null, "addComp", CompToNode(scd).Clone());
        }
    }

static void AddOverride(DocNode ovs, int local, string comp, string prop, DocNode value)
    {
        var o = DocNode.Map();
        o.Add("node", DocNode.Scal(local.ToString(CultureInfo.InvariantCulture)));
        if (comp != null)
            o.Add("comp", DocNode.Scal(comp));
        o.Add("prop", DocNode.Scal(prop));
        o.Add("value", value);
        ovs.Items.Add(o);
    }

// --- Editor yardimcilari: override tespiti + Revert/Apply icin kaynak erisimi ---

    // g'nin bagli oldugu instance kokunu dondurur (kendisi de olabilir); prefab disiysa null.
    public GoDoc PrefabRootOf(GoDoc g)
        => g.IsPrefabRoot ? g : g.PrefabRootId != 0 ? FindById(g.PrefabRootId) : null;

// g'nin prefab kaynak node'u + kok kaydi. false = prefab'a bagli degil / prefab kayip.
    public bool TryGetPrefabSource(GoDoc g, AssetDatabase assets,
        out SceneDoc prefabDoc, out GoDoc sourceNode, out GoDoc rootRec)
    {
        prefabDoc = null;
        sourceNode = null;
        rootRec = PrefabRootOf(g);
        if (rootRec == null || g.PrefabLocalId == 0)
            return false;
        prefabDoc = assets?.LoadPrefab(rootRec.PrefabGuid)?.Doc;
        if (prefabDoc == null)
            return false;
        foreach (var pl in prefabDoc.Objects)
            if (pl.Id == g.PrefabLocalId)
            {
                sourceNode = pl;
                return true;
            }
        return false;
    }

// cd'nin GO icindeki adresi ("Tip:ayniTiptenKacinci").
    public static string CompAddressOf(GoDoc g, CompDoc cd)
    {
        int idx = 0;
        foreach (var c in g.Components)
        {
            if (c == cd)
                break;
            if (c.Type == cd.Type)
                idx++;
        }
        return cd.Type + ":" + idx;
    }

// Prefab'taki alan degerinin sahne uzayina REMAP edilmis klonu (yoksa null).
    public static DocNode RemappedPrefabValue(CompDoc sourceComp, SerializedType.FieldSchema f,
        Dictionary<int, int> map)
    {
        DocNode src = null;
        foreach (var kv in sourceComp.Props)
            if (kv.Key == f.Name || (f.FormerName != null && kv.Key == f.FormerName))
            {
                src = kv.Value;
                break;
            }
        if (src == null)
            return null;
        var clone = src.Clone();
        RemapValue(clone, f, map);
        return clone;
    }

// Map'in tersi (sceneId -> localId): Apply'da sahne degeri prefab uzayina cevrilir.
    public static Dictionary<int, int> InvertMap(Dictionary<int, int> map)
    {
        var inv = new Dictionary<int, int>(map.Count);
        foreach (var kv in map)
            inv[kv.Value] = kv.Key;
        return inv;
    }

// Tiplendirilmis erisimciler (tween/binding/inspector sicak yollari — boxing yok).
        // Editorde expression-compile ile TEMBEL doldurulur; release/AOT'de source
        // generator ayni slotlara duz kod basar.
        public Func<Component, float> GetFloat;

// Float/Int alan icin erisimcileri kurar (alan basina BIR KEZ; cagri ~2-3ns).
    public static void EnsureFloatAccessors(FieldSchema f)
    {
        if (f.SetFloat != null)
            return;
        var comp = System.Linq.Expressions.Expression.Parameter(typeof(Component));
        var val = System.Linq.Expressions.Expression.Parameter(typeof(float));
        var fld = System.Linq.Expressions.Expression.Field(
            System.Linq.Expressions.Expression.Convert(comp, f.Info.DeclaringType), f.Info);
        if (f.Kind == Kind.Int)
        {
            f.SetFloat = System.Linq.Expressions.Expression.Lambda<Action<Component, float>>(
                System.Linq.Expressions.Expression.Assign(fld,
                    System.Linq.Expressions.Expression.Convert(val, typeof(int))), comp, val).Compile();
            f.GetFloat = System.Linq.Expressions.Expression.Lambda<Func<Component, float>>(
                System.Linq.Expressions.Expression.Convert(fld, typeof(float)), comp).Compile();
        }
        else
        {
            f.SetFloat = System.Linq.Expressions.Expression.Lambda<Action<Component, float>>(
                System.Linq.Expressions.Expression.Assign(fld, val), comp, val).Compile();
            f.GetFloat = System.Linq.Expressions.Expression.Lambda<Func<Component, float>>(
                fld, comp).Compile();
        }
    }

static FieldSchema[] Build(Type t, int depth, bool insideStruct)
    {
        var list = new List<FieldSchema>();
        // Base-once: private [SerializeField] alanlar yalniz bildiren tipte gorunur,
        // hiyerarsi yukaridan asagi yurunur (kararli cikti sirasi).
        var chain = new List<Type>();
        for (var tt = t; tt != null && tt != typeof(Component) && tt != typeof(object) && tt != typeof(ValueType); tt = tt.BaseType)
            chain.Add(tt);
        chain.Reverse();
        foreach (var tt in chain)
        {
            foreach (var fi in tt.GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly))
            {
                // NotSerialized/Serializable flag'leri dogrudan okunur. SYSLIB0050
                // yanlis pozitif: uyari BinaryFormatter icin, biz kendi serializer'imizda
                // ayni metadata'yi Unity semantigiyle kullaniyoruz.
#pragma warning disable SYSLIB0050
                bool serialized = (fi.IsPublic && (fi.Attributes & FieldAttributes.NotSerialized) == 0)
                    || fi.GetCustomAttribute<SerializeFieldAttribute>() != null;
#pragma warning restore SYSLIB0050
                if (!serialized)
                    continue;
                var f = BuildField(fi, depth, insideStruct);
                if (f != null)
                    list.Add(f);
            }
        }
        return list.ToArray();
    }

static FieldSchema BuildField(FieldInfo fi, int depth, bool insideStruct)
    {
        var ft = fi.FieldType;
        FieldSchema f = null;

        if (TryKind(ft, out var k))
        {
            if (insideStruct && k is Kind.GoRef or Kind.CompRef)
                return null; // struct kopya semantigi deferred ref cozumuyle celisir
            f = new FieldSchema { Kind = k };
        }
        else if (ft.IsArray || (ft.IsGenericType && ft.GetGenericTypeDefinition() == typeof(List<>)))
        {
            var elem = ft.IsArray ? ft.GetElementType() : ft.GetGenericArguments()[0];
            if (TryKind(elem, out var ek))
            {
                if (insideStruct && ek is Kind.GoRef or Kind.CompRef)
                    return null;
                f = new FieldSchema { Kind = Kind.List, ElementKind = ek, ElementType = elem };
            }
            else if (IsInlineObject(elem) && depth < MaxDepth)
            {
                f = new FieldSchema
                {
                    Kind = Kind.List,
                    ElementKind = Kind.Object,
                    ElementType = elem,
                    Nested = Build(elem, depth + 1, insideStruct || elem.IsValueType),
                };
            }
        }
        else if (IsInlineObject(ft) && depth < MaxDepth)
        {
            f = new FieldSchema
            {
                Kind = Kind.Object,
                ElementType = ft,
                Nested = Build(ft, depth + 1, insideStruct || ft.IsValueType),
            };
        }

        if (f == null)
            return null;
        f.Name = fi.Name;
        f.Info = fi;
        f.FormerName = fi.GetCustomAttribute<FormerlySerializedAsAttribute>()?.OldName;
        return f;
    }

public static FieldSchema Find(FieldSchema[] schema, string name)
    {
        for (int i = 0; i < schema.Length; i++)
            if (schema[i].Name == name)
                return schema[i];
        for (int i = 0; i < schema.Length; i++)
            if (schema[i].FormerName == name)
                return schema[i]; // [FormerlySerializedAs]: eski adla eslesme
        return null;
    }

static DocNode WriteValue(object v, Kind kind, FieldSchema f, GoEncoder goEnc, CompEncoder compEnc, AssetDatabase assets)
    {
        switch (kind)
        {
            case Kind.GoRef:
                return DocNode.Scal(goEnc((GameObject)v));
            case Kind.CompRef:
                return DocNode.Scal(compEnc((Component)v));
            case Kind.Texture:
                {
                    // GUID varsa guid yazilir (tasima/rename kirmaz); yoksa yol.
                    var name = (v as Texture)?.Name ?? "";
                    return DocNode.Scal(assets?.PathToGuid(name) ?? name);
                }
            case Kind.List:
                {
                    var seq = DocNode.Seq();
                    if (v is System.Collections.IList list)
                        foreach (var item in list)
                            seq.Items.Add(WriteValue(item, f.ElementKind, f, goEnc, compEnc, assets));
                    return seq;
                }
            case Kind.Object:
                {
                    var map = DocNode.Map();
                    if (v != null && f.Nested != null)
                        foreach (var nf in f.Nested)
                            map.Add(nf.Name, WriteField(v, nf, goEnc, compEnc, assets));
                    return map;
                }
            default:
                return DocNode.Scal(Format(v, kind));
        }
    }

public static void ReadField(object owner, FieldSchema f, DocNode node, AssetDatabase assets, RefSink defer)
    {
        switch (f.Kind)
        {
            case Kind.GoRef:
            case Kind.CompRef:
                defer(f.Kind, node.Scalar ?? "", v => f.Info.SetValue(owner, v));
                return;
            case Kind.List:
                {
                    if (node.Items == null)
                        return;
                    int count = node.Items.Count;
                    var ft = f.Info.FieldType;
                    if (ft.IsArray)
                    {
                        var arr = Array.CreateInstance(f.ElementType, count);
                        for (int i = 0; i < count; i++)
                            ReadElement(node.Items[i], f, assets, defer, arr, i);
                        f.Info.SetValue(owner, arr);
                    }
                    else
                    {
                        var list = (System.Collections.IList)Activator.CreateInstance(ft);
                        for (int i = 0; i < count; i++)
                        {
                            list.Add(f.ElementType.IsValueType ? Activator.CreateInstance(f.ElementType) : null);
                            ReadElement(node.Items[i], f, assets, defer, list, i);
                        }
                        f.Info.SetValue(owner, list);
                    }
                    return;
                }
            case Kind.Object:
                {
                    if (node.Fields == null)
                        return;
                    object inst = f.Info.GetValue(owner) ?? Activator.CreateInstance(f.ElementType);
                    ReadObjectInto(inst, f.Nested, node, assets, defer);
                    f.Info.SetValue(owner, inst); // struct: boxed kopya geri yazilir
                    return;
                }
            default:
                f.Info.SetValue(owner, Parse(node.Scalar ?? "", f.Kind, f.Info.FieldType, assets));
                return;
        }
    }

static void ReadElement(DocNode node, FieldSchema f, AssetDatabase assets, RefSink defer,
        object container, int index)
    {
        switch (f.ElementKind)
        {
            case Kind.GoRef:
            case Kind.CompRef:
                defer(f.ElementKind, node.Scalar ?? "", v => SetAt(container, index, v));
                return;
            case Kind.Object:
                {
                    object inst = Activator.CreateInstance(f.ElementType);
                    ReadObjectInto(inst, f.Nested, node, assets, defer);
                    SetAt(container, index, inst);
                    return;
                }
            default:
                SetAt(container, index, Parse(node.Scalar ?? "", f.ElementKind, f.ElementType, assets));
                return;
        }
    }

static void SetAt(object container, int index, object value)
    {
        if (container is Array arr)
            arr.SetValue(value, index);
        else
            ((System.Collections.IList)container)[index] = value;
    }

static void ReadObjectInto(object inst, FieldSchema[] schema, DocNode map, AssetDatabase assets, RefSink defer)
    {
        if (schema == null || map.Fields == null)
            return;
        foreach (var kv in map.Fields)
        {
            var nf = Find(schema, kv.Key);
            if (nf != null)
                ReadField(inst, nf, kv.Value, assets, defer);
        }
    }

static bool TryKind(Type ft, out Kind k)
    {
        if (ft == typeof(float)) { k = Kind.Float; return true; }
        if (ft == typeof(int)) { k = Kind.Int; return true; }
        if (ft == typeof(bool)) { k = Kind.Bool; return true; }
        if (ft == typeof(string)) { k = Kind.String; return true; }
        if (ft.IsEnum) { k = Kind.Enum; return true; }
        if (ft == typeof(Vec2)) { k = Kind.Vec2; return true; }
        if (ft == typeof(Vec3)) { k = Kind.Vec3; return true; }
        if (ft == typeof(Color)) { k = Kind.Color; return true; }
        if (ft == typeof(Texture)) { k = Kind.Texture; return true; }
        if (ft == typeof(GameObject)) { k = Kind.GoRef; return true; }
        if (typeof(Component).IsAssignableFrom(ft)) { k = Kind.CompRef; return true; }
        k = default;
        return false;
    }

// --- Kanonik string bicimleri (YAML skalarlariyla birebir) ---

    public static string Format(object v, Kind k) => k switch
    {
        Kind.Float => ((float)v).ToString("R", CultureInfo.InvariantCulture),
        Kind.Int => ((int)v).ToString(CultureInfo.InvariantCulture),
        Kind.Bool => (bool)v ? "true" : "false",
        Kind.String => (string)v ?? "",
        Kind.Enum => v.ToString(),
        Kind.Vec2 => FormatVec2((Vec2)v),
        Kind.Vec3 => FormatVec3((Vec3)v),
        Kind.Color => FormatColor((Color)v),
        Kind.Texture => (v as Texture)?.Name ?? "", // asset anahtari (AssetDatabase key)
        // Go/CompRef sahne baglami ister (localId haritasi) — SceneDoc ozel isler.
        Kind.GoRef or Kind.CompRef => "",
        _ => "",
    };

static Vec2 ParseVec2(string s)
    {
        var p = s.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        return new Vec2(PF(p, 0), PF(p, 1));
    }

internal static Vec3 ParseVec3(string s)
    {
        var p = s.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        return new Vec3(PF(p, 0), PF(p, 1), PF(p, 2));
    }

static Color ParseColor(string s)
    {
        if (s.Length < 9 || s[0] != '#')
            return Color.White;
        return new Color(HexByte(s, 1), HexByte(s, 3), HexByte(s, 5), HexByte(s, 7));
    }

// Tip metaverisinin TEK sahibi — motor assembly'sinde statik Type cache YOK:
// oyun assembly'si reload edilince katalog atilip yeniden kurulur (bayat Type
// koklenmez, AssemblyLoadContext bosalabilir). Editor: FromReflection. Release/
// AOT: source generator ayni Register cagrilarini duz kod olarak uretecek
// (Activator/GetMethod/FieldInfo yok). Katalog yalniz serilestirme yollarindan
// gecer; AddComponent<T> generic hizli yolu (TypeFlags<T>) katalogsuzdur.
public sealed class TypeCatalog
{
}
