        if (Items != null)
        {
            n.Items = new List<DocNode>(Items.Count);
            foreach (var it in Items)
                n.Items.Add(it.Clone());
        }
        if (Fields != null)
        {
            n.Fields = new List<KeyValuePair<string, DocNode>>(Fields.Count);
            foreach (var kv in Fields)
