public static DocNode Parse(string text)
    {
        var lines = Tokenize(text);
        int i = 0;
        return ParseMap(lines, ref i, 0);
    }

static List<Line> Tokenize(string text)
    {
        var list = new List<Line>();
        foreach (var raw in text.Split('\n'))
        {
            var line = raw.TrimEnd('\r', ' ');
            if (line.Length == 0)
                continue;
            int indent = 0;
            while (indent < line.Length && line[indent] == ' ')
                indent++;
            var body = line.Substring(indent);
            if (body.StartsWith("#"))
                continue;
            var ln = new Line { Indent = indent };
            if (body.StartsWith("- "))
            {
                ln.Item = true;
                body = body.Substring(2);
            }
            else if (body == "-")
            {
                ln.Item = true;
                body = "";
            }
            // "key: val" / "key:" ayrimi — tirnakli skaler ':' icerebilir,
            // o yuzden tirnakla baslayan govde anahtar sayilmaz.
            int colon = body.StartsWith("'") ? -1 : body.IndexOf(": ", System.StringComparison.Ordinal);
            if (colon < 0 && body.EndsWith(":") && !body.StartsWith("'"))
                colon = body.Length - 1;
            if (colon >= 0)
            {
                ln.HasKey = true;
                ln.Key = body.Substring(0, colon).Trim();
                ln.Val = Unquote(colon + 1 < body.Length ? body.Substring(colon + 1).Trim() : "");
            }
            else
            {
                ln.Val = Unquote(body.Trim());
            }
            list.Add(ln);
        }
        return list;
    }

static DocNode ParseBlock(List<Line> l, ref int i, int minIndent)
    {
        if (i >= l.Count || l[i].Indent < minIndent)
            return DocNode.Scal("");
        int indent = l[i].Indent;
        return l[i].Item ? ParseSeq(l, ref i, indent) : ParseMap(l, ref i, indent);
    }

static DocNode ParseMap(List<Line> l, ref int i, int indent)
    {
        var map = DocNode.Map();
        while (i < l.Count && l[i].Indent == indent && !l[i].Item && l[i].HasKey)
        {
            var ln = l[i];
            i++;
            if (ln.Val.Length > 0)
                map.Add(ln.Key, DocNode.Scal(ln.Val));
            else if (i < l.Count && l[i].Indent > indent)
                map.Add(ln.Key, ParseBlock(l, ref i, indent + 1));
            else
                map.Add(ln.Key, DocNode.Scal(""));
        }
        return map;
    }

static DocNode ParseSeq(List<Line> l, ref int i, int indent)
    {
        var seq = DocNode.Seq();
        while (i < l.Count && l[i].Indent == indent && l[i].Item)
        {
            var ln = l[i];
            if (!ln.HasKey)
            {
                seq.Items.Add(DocNode.Scal(ln.Val));
                i++;
                continue;
            }
            // Harita ogesi: "- key: val" ilk alani, devami +2 sutunda —
            // satiri normal harita satirina cevirip ParseMap'e devret.
            l[i] = new Line { Indent = indent + 2, Item = false, HasKey = true, Key = ln.Key, Val = ln.Val };
            seq.Items.Add(ParseMap(l, ref i, indent + 2));
        }
        return seq;
    }

static string Unquote(string s)
    {
        if (s.Length >= 2 && s[0] == '\'' && s[^1] == '\'')
            return s.Substring(1, s.Length - 2).Replace("''", "'");
        return s;
    }

// Fragment govdesinden tam GLSL shader kurar (ortak vertex + sarilmis fragment).
    public static Shader CreateEffect(string fragmentBody)
    {
        string fragmentSource = _fragPrefix + fragmentBody + _fragSuffix;

        byte[] vs = Ascii(_vertexSource);
        byte[] fs = Ascii(fragmentSource);

        Sokol.ShaderBegin();
        fixed (byte* p = vs) Sokol.ShaderVertexSource(p);
        fixed (byte* p = fs) Sokol.ShaderFragmentSource(p);

        for (int i = 0; i < 9; i++)
            fixed (byte* np = _attrNames[i])
                Sokol.ShaderAttr(i, np, SG.ShaderAttrBaseTypeFloat);

        // vertex uniform block 0: mat4 u_viewProj (std140).
        Sokol.ShaderUniformBlock(0, SG.ShaderStageVertex, 64, SG.UniformLayoutStd140);
        fixed (byte* np = _uViewProj)
            Sokol.ShaderUniform(0, 0, SG.UniformTypeMat4, np);

        // fragment doku view + sampler + eslesme ("tex").
        Sokol.ShaderTextureView(0, SG.ShaderStageFragment, SG.ImageType2D, SG.ImageSampleTypeFloat);
        Sokol.ShaderSampler(0, SG.ShaderStageFragment, SG.SamplerTypeFiltering);
        fixed (byte* np = _texName)
            Sokol.ShaderTextureSamplerPair(0, SG.ShaderStageFragment, 0, 0, np);

        return new Shader { Handle = Sokol.ShaderEnd() };
    }

