                {
                    _localMatrix.m[0] = _scale.x;
                    _localMatrix.m[1] = 0;
                    _localMatrix.m[2] = 0;
                    _localMatrix.m[4] = 0;
                    _localMatrix.m[5] = _scale.y;
                    _localMatrix.m[6] = 0;
                    _localMatrix.m[8] = 0;
                    _localMatrix.m[9] = 0;
                    _localMatrix.m[10] = _scale.z;
                    _localMatrix.m[12] = _position.x - _scale.x * px;
                    _localMatrix.m[13] = _position.y - _scale.y * py;
                    _localMatrix.m[14] = _position.z;
