        ref var s = ref _slots[i];
        int gen = s.Gen;
        s.Alive = true;
        s.Waiting = false;
        s.HasFrom = false;
        s.Yoyo = false;
        s.Forward = true;
        s.Channel = ch;
        s.Ease = DigitoyEngine.Ease.Linear;
        s.LoopsLeft = 1;
        s.Delay = 0f;
        s.T = 0f;
        s.Duration = duration > 1e-6f ? duration : 1e-6f;
        s.ToX = toX; s.ToY = toY; s.ToZ = toZ; s.ToW = toW;
        s.Target = target;
        s.Field = field;
        s.Curve = null;
        s.OnDone = null;
        s.Next = -1;
